package com.exito.chop;
import org.json.*;import android.net.Uri;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;
final class History {
 final Engine e;final File directory,assets;EditJournal journal;final WeakHashMap<short[],String> ids=new WeakHashMap<>();Snapshot before;String label;volatile int undoCount,redoCount;volatile boolean restoring;
 static final class Asset {final short[] pcm;final int rate;final String id;Asset(short[] p,int r,String i){pcm=p;rate=r;id=i;}}
 static final class Snapshot {final String json;final ArrayList<Asset> audio;Snapshot(String j,ArrayList<Asset> a){json=j;audio=a;}}
 History(Engine engine){e=engine;directory=new File(e.context.getFilesDir(),"history-v3");assets=new File(directory,"audio");assets.mkdirs();try{journal=new EditJournal(directory);counts();}catch(Exception ex){e.status="Historial: "+Engine.reason(ex);}}
 synchronized String id(short[] p){if(p==null)return "";String id=ids.get(p);if(id==null){id=UUID.randomUUID().toString();ids.put(p,id);}return id;}
 Snapshot snapshot()throws Exception{e.slots.save();ArrayList<Asset> audio=new ArrayList<>();JSONArray slots=new JSONArray();for(Slots.Slot s:e.slots.list){String id=id(s.source);JSONObject o=slot(s).put("audioId",id);slots.put(o);if(s.source!=null)audio.add(new Asset(s.source,s.rate,id));}String drum=id(e.drums.pcm);if(e.drums.pcm!=null)audio.add(new Asset(e.drums.pcm,e.drums.rate,drum));JSONObject root=new JSONObject().put("version",3).put("manualPadsDefault",true).put("latencyMs",e.latencyMs).put("active",e.slots.active).put("bpm",e.slots.masterBpm).put("key",e.slots.masterKey).put("slots",slots).put("requested",e.requestedChops).put("threshold",e.thresholdDb).put("comp",e.compression).put("reverb",e.reverb).put("gate",e.gate).put("playToEnd",e.playToEnd).put("linkProject",e.linkProject).put("captureVideo",e.captureVideo).put("fx",SettingsIO.write(e.mutate)).put("heat",SettingsIO.write(e.heat)).put("harmony",SettingsIO.write(e.harmony.settings)).put("buses",e.buses.json()).put("masterColour",masterColourJson(e.masterColour)).put("stepSources",new JSONArray(e.sequencer.source)).put("stepPads",new JSONArray(e.sequencer.pad)).put("stepLevels",new JSONArray(e.sequencer.level)).put("drums",new JSONObject().put("audioId",drum).put("rate",e.drums.rate).put("name",e.drums.name).put("original",e.drums.originalBpm).put("bpm",e.drums.bpm).put("volume",e.drums.volume));return new Snapshot(root.toString(),audio);}
 static JSONObject slot(Slots.Slot s)throws Exception{return new JSONObject().put("loaded",s.source!=null).put("name",s.name).put("rate",s.rate).put("bpm",s.bpm).put("key",s.key).put("pitch",s.pitch).put("tempo",s.tempo).put("selected",s.selected).put("mode",s.mode).put("youtube",s.youtube).put("video",s.video==null?"":s.video.toString()).put("mono",s.mono).put("videoOffsetMs",s.videoOffsetMs).put("cuts",new JSONArray(s.cuts==null?new int[]{0,1}:s.cuts)).put("pads",SettingsIO.pads(s.pads));}
 static JSONObject masterColourJson(MasterColour.Settings s)throws JSONException{return new JSONObject().put("enabled",s.enabled).put("bits",s.bitsIndex).put("rate",s.rateIndex).put("filter",s.filter).put("cutoff",s.cutoff).put("mix",s.mix);}
 static void readMasterColour(JSONObject o,MasterColour.Settings s){if(o==null){s.reset();return;}s.enabled=o.optBoolean("enabled",false);s.bitsIndex=MasterColour.bound(o.optInt("bits",3),MasterColour.BITS.length);s.rateIndex=MasterColour.bound(o.optInt("rate",7),MasterColour.RATES.length);s.filter=MasterColour.bound(o.optInt("filter",0),3);s.cutoff=MasterColour.limit((float)o.optDouble("cutoff",.82));s.mix=MasterColour.limit((float)o.optDouble("mix",1));}
 synchronized void begin(String name){if(restoring||e.busy||before!=null||journal==null)return;try{before=snapshot();label=name;}catch(Exception ex){e.message("Deshacer: "+Engine.reason(ex));}}synchronized void cancel(){before=null;}
 synchronized void end(){if(before==null||restoring)return;final Snapshot a=before;final String name=label;before=null;try{final Snapshot b=snapshot();if(a.json.equals(b.json))return;e.worker.execute(()->{try{saveAssets(a);saveAssets(b);journal.add(a.json,b.json,name);saveSession(b);counts();e.changed();}catch(Exception ex){e.message("Historial: "+Engine.reason(ex));}});}catch(Exception ex){e.message("Historial: "+Engine.reason(ex));}}
 void edit(String name,Runnable r){if(e.busy||restoring)return;begin(name);try{r.run();}finally{end();e.changed();}}
 void saveAssets(Snapshot s)throws Exception{for(Asset a:s.audio){File target=new File(assets,a.id+".wav");if(target.exists())continue;File tmp=new File(assets,a.id+".tmp");try(OutputStream out=new BufferedOutputStream(new FileOutputStream(tmp))){AudioFiles.writeWav(out,a.pcm,a.rate);}Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
 void saveSession(Snapshot s)throws Exception{File dir=e.slots.directory(),tmp=new File(dir,"state.tmp");Files.write(tmp.toPath(),s.json.getBytes(StandardCharsets.UTF_8));Files.move(tmp.toPath(),new File(dir,"state-v3.json").toPath(),StandardCopyOption.REPLACE_EXISTING);}
 synchronized void clearEdits(){try{if(journal!=null){File[] steps=directory.listFiles((dir,n)->n.endsWith(".edit")||n.equals("cursor")||n.equals("cursor.tmp")||n.equals("entry.tmp"));if(steps!=null)for(File file:steps)file.delete();}journal=new EditJournal(directory);counts();before=null;}catch(Exception ex){e.message("Historial nuevo: "+Engine.reason(ex));}}
 void counts(){undoCount=journal.undoCount();redoCount=journal.redoCount();}
 void move(boolean redo){if(restoring||e.busy)return;end();e.freezeForEdit();e.harmony.stop();e.sequencer.stop();e.drums.stop();e.stop();restoring=e.busy=true;e.message(redo?"Rehaciendo…":"Deshaciendo…");e.worker.execute(()->{try{String text=journal.peek(redo);if(text==null){e.main.post(()->{e.busy=restoring=false;e.message("No hay más pasos en esa dirección");});return;}Runnable apply=prepare(new JSONObject(text));journal.moved(redo);counts();e.main.post(()->{apply.run();e.busy=restoring=false;e.message(redo?"Paso rehecho":"Paso deshecho");});Files.write(new File(e.slots.directory(),"state-v3.json").toPath(),text.getBytes(StandardCharsets.UTF_8));}catch(Throwable ex){e.main.post(()->{e.busy=restoring=false;e.message("Historial: "+Engine.reason(ex));});}});}
 short[] audio(String id,int[] rate)throws Exception{if(id.isEmpty())return null;synchronized(this){for(Map.Entry<short[],String> x:ids.entrySet())if(id.equals(x.getValue())&&x.getKey()!=null)return x.getKey();}AudioFiles.Sample s=AudioFiles.decode(e.context,Uri.fromFile(new File(assets,id+".wav")));rate[0]=s.rate;synchronized(this){ids.put(s.pcm,id);}return s.pcm;}
 Runnable prepare(JSONObject root)throws Exception{Slots.Slot[] all=new Slots.Slot[8];JSONArray json=root.getJSONArray("slots");long used=0;for(int i=0;i<8;i++){JSONObject o=json.optJSONObject(i);Slots.Slot s=new Slots.Slot();all[i]=s;if(o==null||!o.optBoolean("loaded"))continue;s.name=o.optString("name","Fuente");s.rate=o.optInt("rate",44100);s.bpm=o.optInt("bpm",90);s.key=Math.max(0,Math.min(23,o.optInt("key",0)));s.pitch=(float)o.optDouble("pitch",0);s.tempo=(float)o.optDouble("tempo",1);s.selected=o.optInt("selected");s.mode=o.optString("mode","regions");s.mono=o.optBoolean("mono",true);s.videoOffsetMs=o.optLong("videoOffsetMs",0);s.youtube=o.optString("youtube","");String video=o.optString("video","");if(!video.isEmpty())s.video=Uri.parse(video);JSONArray cuts=o.optJSONArray("cuts");s.cuts=new int[cuts==null?2:cuts.length()];if(cuts!=null)for(int j=0;j<s.cuts.length;j++)s.cuts[j]=cuts.getInt(j);s.pads=SettingsIO.pads(o.optJSONArray("pads"));String id=o.optString("audioId","");int[] sr={s.rate};if(!id.isEmpty())s.source=audio(id,sr);else{File f=new File(e.slots.directory(),"source-"+i+".wav");if(f.exists()){AudioFiles.Sample a=AudioFiles.decode(e.context,Uri.fromFile(f));s.source=a.pcm;sr[0]=a.rate;}}s.rate=sr[0];if(s.source==null)continue;used+=s.source.length*4L;if(used>Runtime.getRuntime().maxMemory()*.75)throw new IOException("No cabe esta sesión completa en RAM");s.rendered=Dsp.stretch(s.source,s.rate,s.tempo,(float)Math.pow(2,s.pitch/12.));s.waveform=Dsp.peaks(s.source,4096);if(cuts==null)s.cuts=new int[]{0,s.source.length/2};if(!root.optBoolean("manualPadsDefault")&&(s.mode.equals("regions")||s.mode.equals("threshold"))){s.mode=PadChops.EMPTY;s.cuts=new int[]{0,s.source.length/2};s.pads=PadParams.defaults();s.selected=0;}}
 JSONObject d=root.optJSONObject("drums");int[] sr={d==null?44100:d.optInt("rate",44100)};short[] drum=d==null?null:audio(d.optString("audioId",""),sr);int original=d==null?90:d.optInt("original",90),bpm=d==null?90:d.optInt("bpm",90);short[] dr=drum==null?null:Dsp.stretch(drum,sr[0],bpm/(float)original,1);
 return ()->{try{for(int i=0;i<8;i++)e.slots.list[i]=all[i];e.slots.active=Math.max(0,Math.min(7,root.optInt("active",0)));e.slots.masterBpm=root.optInt("bpm",90);e.slots.masterKey=root.optInt("key",0);e.latencyMs=Math.max(0,Math.min(500,root.optInt("latencyMs",0)));e.requestedChops=root.optInt("requested",16);e.thresholdDb=(float)root.optDouble("threshold",-24);e.compression=(float)root.optDouble("comp",0);e.reverb=(float)root.optDouble("reverb",0);e.gate=root.optBoolean("gate");e.playToEnd=root.optBoolean("playToEnd");e.linkProject=root.optBoolean("linkProject",true);e.captureVideo=root.optBoolean("captureVideo",true);SettingsIO.read(root.optJSONObject("fx"),e.mutate);SettingsIO.read(root.optJSONObject("heat"),e.heat);SettingsIO.read(root.optJSONObject("harmony"),e.harmony.settings);e.buses.read(root.optJSONObject("buses"));readMasterColour(root.optJSONObject("masterColour"),e.masterColour);e.output.masterColour.reset();JSONArray ss=root.optJSONArray("stepSources"),sp=root.optJSONArray("stepPads");if(ss!=null&&sp!=null)for(int i=0;i<16;i++){e.sequencer.source[i]=ss.optInt(i,-1);e.sequencer.pad[i]=sp.optInt(i,-1);e.sequencer.level[i]=Math.max(1,Math.min(16,root.optJSONArray("stepLevels")==null?16:root.optJSONArray("stepLevels").optInt(i,16)));}e.drums.pcm=drum;e.drums.rendered=dr;e.drums.rate=sr[0];e.drums.bpm=bpm;e.drums.originalBpm=original;if(d!=null){e.drums.name=d.optString("name","Drums");e.drums.volume=(float)d.optDouble("volume",.55);}e.slots.apply();}catch(Exception error){e.message("Ajustes: "+Engine.reason(error));}};}
}
